  // Orchestrator (command deck brain) settings
  'settings.orchestrator': 'Orchestrator',
  'settings.orchestratorBrain': 'Orchestrator runtime',
  'settings.orchestratorBrainDesc':
    'Which agent runtime drives the orchestrator. The terminal runtime is the default — it drives your own claude binary on your subscription. Hermes (ACP) requires the Hermes Agent CLI installed and authenticated on this machine — run its own setup first. Applies from the next orchestrator turn; each runtime keeps its own conversation history.',
  'settings.orchestratorBrainClaude': 'Claude Code (SDK)',
  'settings.orchestratorBrainClaudePty': 'Claude Code (terminal, default) — subscription',
  'settings.orchestratorBrainHermes': 'Hermes Agent (ACP) — experimental',
  // D2 — role → agent/model enforcement editor (Settings › Orchestrator).
  'settings.roleBindings': 'Role → model enforcement',
  'settings.roleBindingsDesc':
    'Pin an agent and model to each role. Launches that wmux itself assembles for a pane carrying that role run with the bound model: agent launches the orchestrator issues, the seeded command of a project pane whose wmux.json leaf declares a role, and the pane resume command. A launcher you type into the terminal yourself is not rewritten. Leave a row blank to keep the role unbound.',
  'settings.roleBindingAgentPlaceholder': 'agent',
  'settings.roleBindingModelPlaceholder': 'model (optional)',
  'settings.roleBindingArgsPlaceholder': 'extra args (optional)',
  'settings.roleBindingAgentLabel': '{role} agent',
  'settings.roleBindingModelLabel': '{role} model',
  'settings.roleBindingArgsLabel': '{role} extra args',
  'settings.roleBindingHintNoAgent':
    'Pick an agent too — a model on its own is not enforced (wmux can’t tell whose --model flag it is).',
  'settings.roleBindingHintNoGrammar':
    'wmux has no verified --model flag for {agent}, so the model is ignored. Extra args still apply.',
  'settings.roleBindingHintInert': 'Add a model, an effort, skip permissions, fresh context or extra args — an agent alone enforces nothing.',
  'settings.roleBindingHintFreshContextInert':
    'Fresh context per task works only with claude or codex as the agent; for this role it does nothing.',
  'settings.roleBindingEffortLabel': '{role} effort',
  'settings.roleBindingEffortDefault': 'Effort: default',
  'settings.roleBindingSkipPermissions': 'Skip permissions',
  'settings.roleBindingFreshContext': 'Fresh context per task',
  'settings.roleBindingFreshContextTooltip':
    'When this pane is handed a NEW task (the orchestrator’s terminal_send with new_task, or a new send_message from another agent), wmux first types {command} so the previous task’s conversation does not carry over. Never on a follow-up or a reply. Skipped while the agent is busy or the pane still has other open agent tasks.',
  'settings.roleBindingRefreshModels': 'Refresh models',
  'settings.rolePresetApply': 'Apply {role} preset',
  'settings.rolePresetApplied': '{role} preset applied',
  'settings.rolePresetApplyBypass':
    'Apply {role} preset (skips permission prompts)',
  'settings.rolePresetTooltipNoSkip':
    'Sets this role to {tier} effort, keeping the agent, model and extra args you chose. This agent has no verified skip-permissions flag, so its permission prompts stay on.',
  'settings.rolePresetConfirmBypass':
    'Apply the {role} preset? It turns on skip permissions: every {role} launch, including fan-out tasks routed to {role}, will edit files and run commands without asking you first.',
  'settings.rolePresetTooltip':
    'Sets this role to {tier} effort AND turns on skip permissions: every {role} launch, including fan-out tasks routed to {role}, runs without permission prompts. Keeps the agent, model and extra args you chose; only an empty agent (agy) or model is filled in. For agy the effort is the model suffix, so a Flash model moves to its {tier} variant and any other model is left as is. Tool, skill and MCP settings are not per role for agy; they stay shared by every role.',
