  'settings.fanoutWorkerPermissionMode': 'Worker permission mode',
  'settings.fanoutWorkerPermissionModeDesc': 'The Claude Code permission mode each fan-out worker launches with. In every mode workers may record their ledger row and read their mission channel without a prompt, and may never fan out, type into other panes, message other agents or drive the browser.',
