  'settings.startupDirectory': 'Starting directory',
  'settings.startupDirectoryDesc': 'New terminals start here. Empty = your home directory. Workspace profiles can override per workspace.',
  'settings.startupDirectoryPlaceholder': 'e.g. C:\\Projects',
  'settings.splitInheritsCwd': 'Splits inherit directory',
  'settings.splitInheritsCwdDesc': 'A pane created by splitting starts in the original pane\'s current directory.',
  'settings.closeTabOnShellExit': 'Close the tab when its shell exits cleanly',
  'settings.closeTabOnShellExitDesc': 'Typing exit or pressing Ctrl+D closes the tab. A shell that ends with an error, and a pane wmux restarts on its own, stay open.',
  'settings.plainDragSelect': "Select text by dragging, even when the app uses the mouse",
  'settings.plainDragSelectDesc': "A plain drag selects text even in apps that use the mouse, such as Codex; a click still goes to the app. Hold Shift (macOS) or Alt (Windows, Linux) while dragging to send the drag to the app instead.",
  'settings.imeResidueGuard': 'Clear IME residue while idle',
  'settings.imeResidueGuardDesc': 'Protects against voice-input tools that replace leftover IME text destructively. Leave off unless you use such a tool — the clearing can confuse some IMEs.',
  'settings.hiddenPaneRetention': 'Pause hidden pane rendering',
  'settings.hiddenPaneRetentionDesc': 'Default on. Hidden panes pause screen rendering while everything keeps running — output is captured by the daemon and the pane catches up when you switch back (briefly shown as "catching up"). Turn off to render every hidden pane continuously; that costs real CPU per busy hidden pane. Daemon sessions only; local-mode sessions always render.',
  'settings.coldPark': 'Unload idle hidden workspaces',
  'settings.inlineImages': 'Inline images',
  'settings.inlineImagesDesc': 'Draw images that terminal programs print with sixel or the iTerm2 image protocol (OSC 1337) inside the pane. Each pane keeps at most 64 MB of images; older ones are replaced by a placeholder. Turn off to ignore image output and free that memory.',
  'settings.coldParkDesc': 'Default on. A workspace you have not looked at in a few minutes has its terminals unloaded to free memory, so RAM stops growing with the number of workspaces you keep open. The sessions keep running in the daemon; switching back reloads the workspace and replays its screen from the daemon. Turn off to keep every workspace loaded for instant reveals. Daemon sessions only.',
  'settings.browserBackend': 'Browser backend',
  'settings.browserBackendDesc': 'Where agent-driven browser opens go. Built-in opens embedded browser panes inside wmux with the full automation toolset (clicking, screenshots, data extraction). External sends opens to your real, signed-in default browser instead — only open and navigate work; deep automation (click, screenshot, etc.) is disabled and wmux spawns no embedded browser. External is global: every workspace opens into your one shared browser session, so any agent can pop a tab there. Chrome launches a dedicated real-Chrome instance with its own persistent profile (sign in once, logins stick) and gives agents the full automation toolset — separate from your daily browser. Each workspace can bind its own Chrome profile from its workspace-card context menu (separate logins per workspace).',
  'settings.browserBackendBuiltin': 'Built-in (embedded panes)',
  'settings.browserBackendExternal': 'External (your default browser)',
  'settings.browserBackendChrome': 'Chrome (dedicated agent browser)',
  'chromeProfiles.menuLabel': 'Chrome profile',
  'chromeProfiles.defaultProfile': 'Default profile',
  'chromeProfiles.newProfile': 'New profile…',
  'chromeProfiles.newPlaceholder': 'Chrome profile name (letters, numbers, - and _)',
  'chromeProfiles.newCreate': 'Create',
  'chromeProfiles.newCancel': 'Cancel',
  'chromeProfiles.lentTabs': 'Tabs lent to agents',
  'chromeProfiles.returnTab': 'Return to me',
  'chromeProfiles.returnTabHint': 'Take this tab back. Agents can no longer act on it',
  'chromeProfiles.untitledTab': 'Untitled tab',
  'chromeProfiles.newFailed': 'Could not create the profile.',
  'chromeProfiles.liveProfile': 'Live Chrome (your browser)',
  'chromeProfiles.liveDesc': 'Attach to your own running Chrome — requires enabling chrome://inspect/#remote-debugging once.',
  'chromeProfiles.liveConfirm': 'Give this workspace’s agent access to your ENTIRE live Chrome — all tabs and logins? Chrome will also ask for permission on each connection.',
  'chromeProfiles.liveConfirmYes': 'Bind live',
  'chromeProfiles.liveConfirmCancel': 'Cancel',
  'settings.browserLightweight': 'Lightweight background browsers',
  'settings.browserLightweightDesc': 'Throttle CPU usage of built-in browser panes that are not visible (hidden workspaces, zoomed-away panes, minimized window). Automation (MCP/screenshots) still runs full-speed. Reduces CPU only, not memory.',
  'settings.browserDiscard': 'Discard hidden browsers (frees memory)',
  'settings.browserDiscardDesc': 'After a browser pane stays invisible for 5 minutes, unload it entirely to reclaim its memory. The page reloads when you return (scroll position and unsaved form input are lost). Panes playing audio are never discarded; automation wakes a discarded pane automatically.',
  'settings.browserPrivateNetwork': 'Allow private network addresses',
  'settings.browserPrivateNetworkDesc': 'Let agent browsers open intranet addresses: 10.x, 172.16–31.x, 192.168.x and fc00::/7. Cloud metadata (169.254.x), link-local and loopback aliases stay blocked. Takes effect on the next navigation. Off by default.',
  'settings.browserPrivateNetworkEnvForced': 'On because WMUX_ALLOW_PRIVATE_NETWORK is set in the environment that launched wmux.',
  'settings.browserPrivateNetworkOffUnsaved': 'Couldn\'t save this. Private network access will turn back on after wmux restarts.',
  'settings.browserPrivateNetworkOnUnsaved': 'Couldn\'t save this setting, so private network access stays off.',
  'settings.siteMemory': 'Per-site memory',
  'settings.siteMemoryDesc': 'Remember what went wrong on a site — a replay that stopped, a host that would not load — and mention it the next time the browser lands there. Stored per workspace, one file per domain, and forgotten after 60 days without a repeat. Turning this off stops both recording and reminding; anything already recorded can still be deleted.',
  'settings.browserSectionRuntime': 'Browser runtime',
  'settings.browserSectionKnowledge': 'Agent site knowledge',
  'settings.siteGuides': 'Site guides',
  'settings.siteGuidesDesc': 'When the browser lands on a page matched by a note in the site-guides folder of the wmux data directory, tell the agent the note exists and where it is. Only the title and path are shared, never the note itself. Any tool allowed to read the browser can ask which notes match a URL and learn their titles and paths, though not their contents. Off by default. It turns on automatically the first time the Chrome agent browser is chosen, and stays as you leave it after that.',
  'settings.updates': 'Updates',
  'settings.wmuxUpdates': 'wmux updates',
  'settings.updateFailed': 'Failed to check for updates',
