  'settings.fontFamilyPlaceholder': 'Type or pick a font…',
  'settings.fontCustom': 'Custom font…',
  'settings.fontCustomPlaceholder': 'Font name (e.g. JetBrainsMonoHangul)',
  'settings.fontNotInstalled': 'not installed',
  'settings.fontApply': 'Apply',
  'settings.fontCancel': 'Cancel',
  'settings.layout': 'Layout',
  'settings.chromePreset': 'Interface visibility',
  'settings.chromePresetDesc': 'Minimal collapses the sidebar and hides the agent toolbar, pane actions, and tools panel. These visibility preferences are saved; adjust them individually or restore Standard.',
  'settings.chromePresetMinimal': 'Apply Minimal',
  'settings.chromePresetStandard': 'Restore Standard',
  'settings.chromePresetApplied': 'Interface visibility updated.',
  'settings.uiScale': 'UI scale',
  'settings.uiScaleDesc': 'Scale the whole interface — useful on high-DPI displays. Restart not required.',
  'settings.sidebarPosition': 'Sidebar position',
  'settings.sidebarPositionDesc': 'Left or right of the terminal area',
  'settings.sidebarAttentionFirst': 'Needs-you rows first',
  'settings.sidebarAttentionFirstDesc': 'Move workspaces whose agent is waiting on you to the top of the sidebar. Off by default: rows stay where you dragged them. While on, drag-to-reorder is paused.',
  'settings.sidebarSort': 'Workspace order',
  'settings.sidebarSortDesc': 'How the sidebar lists workspaces. Attention (the default) puts what needs you first, then errors, finished, running, unconfirmed and idle, and re-sorts only after a short pause or when the pointer leaves the list. Manual keeps the order you dragged. In every order, workspaces pinned to the top stay first in the order you gave them. Drag-to-reorder works in Manual, and among pinned rows in any order.',
  'settings.sidebarSortManual': 'Manual',
  'settings.sidebarSortAttention': 'Attention',
  'settings.sidebarSortRecent': 'Recent activity',
  'settings.sidebarShowExplorerButton': 'Show "Open in File Explorer" button',
  'settings.sidebarShowExplorerButtonDesc': "Show the folder button on sidebar workspace rows. The row's right-click menu keeps the action either way.",
  'settings.sidebarShowCopyInfoButton': 'Show "Copy session info" button',
  'settings.sidebarShowCopyInfoButtonDesc': "Show the button that copies a workspace's session info on sidebar workspace rows.",
  'settings.sidebarShowPorts': 'Show port numbers',
  'settings.sidebarShowPortsDesc': 'Show listening port numbers in sidebar workspace rows.',
  'settings.sidebarShowPaneCoordinates': 'Show pane coordinates',
  'settings.sidebarShowPaneCoordinatesDesc': 'Show the auto-generated w1-2 style coordinate in the agent roster for panes you have not labeled. On by default. A pane you rename always shows its label either way.',
  'settings.attentionBlink': 'Attention blink',
  'settings.attentionBlinkDesc': 'How a sidebar row that waits on a question or approval pulses while its workspace is not on screen. Once + remind (the default) pulses when the wait starts, then again every interval. Reduced motion turns every pulse off.',
  'settings.attentionBlinkOff': 'Off',
  'settings.attentionBlinkOnce': 'Once',
  'settings.attentionBlinkRemind': 'Once + remind',
  'settings.attentionBlinkContinuous': 'Continuous',
  'settings.attentionBlinkRemindEvery': 'Remind every',
  'settings.attentionBlinkRemind30s': '30 s',
  'settings.attentionBlinkRemind1m': '1 min',
  'settings.attentionBlinkRemind5m': '5 min',
  'settings.attentionBlinkFinished': 'Finished turns',
  'settings.attentionBlinkFinishedDesc': 'A finished turn you have not looked at shows a small dot instead of the needs-you border. Pulse once also flashes the row when it finishes.',
  'settings.fleetLayout': 'Fleet layout',
  'settings.fleetLayoutDesc': 'Show Fleet as one attention list, or as a board with Running, Needs you, Finished and Idle columns. The same switch sits in the Fleet header.',
  'settings.attentionBlinkFinishedDot': 'Dot only',
  'settings.attentionBlinkFinishedPulse': 'Pulse once',
  'settings.windowGlass': 'Window glass',
  'settings.windowGlassDesc': 'How much of the desktop shows through the sidebar and the window edge. Panes and terminals stay solid. macOS and Windows 11.',
  'settings.windowGlassOff': 'Off',
  'settings.windowGlassSoft': 'Soft',
  'settings.windowGlassClear': 'Clear',
  'settings.windowGlassUnsupported': 'Needs Windows 11 version 22H2 or later. This Windows keeps a solid window.',
  'settings.sidebarLeft': 'Left',
  'settings.sidebarRight': 'Right',
  'settings.multiviewArrangement': 'Multiview arrangement',
  'settings.multiviewArrangementDesc': 'How workspaces are tiled when several are shown at once. Auto fits them to a grid; Columns puts them side by side; Rows stacks them vertically.',
  'settings.multiviewAuto': 'Auto',
  'settings.multiviewColumns': 'Columns',
  'settings.multiviewRows': 'Rows',
  'settings.paneActionsVisible': 'Pane action buttons',
  'settings.paneNewTerminalButton': 'New-terminal button on the tab strip',
  'settings.paneNewTerminalButtonDesc':
    'Adds a + that puts a SECOND terminal in this pane. wmux is built around one pane = one terminal — splitting is the usual way to get another — so this is off by default. Ctrl+T does the same thing without the button.',
  'settings.paneActionsVisibleDesc': 'Show new-terminal, split, and new-browser buttons in each pane\'s tab strip.',
  'settings.chatView': 'Multi-agent chat view (experimental)',
  'settings.chatViewDesc': 'Add a Terminal / Chat switch for Claude history and separate Codex, OpenCode, or configured ACP chat sessions. Off by default while production qualification continues.',
  'settings.titlebarClock': 'Clock in the titlebar',
  'settings.titlebarClockDesc':
    'Off by default — your OS already shows the time. Turn it on if you run wmux full-screen with the taskbar hidden.',
  'settings.titlebarVitals': 'Always show memory and CPU',
  'settings.titlebarVitalsDesc':
    'Off by default — the memory and CPU chips then appear only when memory use grows large. Turn it on to keep both in the titlebar all the time.',
