  // Notification system expansion (T12)
  'settings.paneRing': 'Pane border ring on new notifications',
  'settings.paneRingDesc': 'Highlights the pane that received a notification with a blue border.',
  'settings.paneGlowDim': 'Unread pane brightness',
  'settings.paneGlowDimDesc': 'How bright a pane stays while it holds an unread glow. 100% disables the shadowing so inactive sessions remain fully readable; 60% is the classic dimmed look.',
  'settings.paneFlash': 'Flash effect on new notification ring',
  'settings.paneFlashDesc': 'Plays a 500ms flash before the steady glow. Skips flash if disabled (goes straight to glow).',
  'settings.taskbarFlash': 'Flash taskbar when window is unfocused',
  'settings.taskbarFlashDesc': 'Triggers Windows taskbar attention when a notification arrives and wmux is hidden.',
  'settings.notificationSoundChoice': 'Notification sound',
  'settings.notificationSoundChoiceDesc': 'default = play the system notification sound. none = silent.',
  'settings.notificationSoundChoiceDefault': 'Default',
  'settings.notificationSoundChoiceNone': 'None',
  'settings.notificationCategories': 'Notification categories',
  'settings.notificationCategoriesDesc': 'Turn off a category to silence its toasts, sounds, rings, and taskbar flashes. Muted categories still appear in the notification panel.',
  'settings.notificationCategory.agent-turn': 'Agent turn finished',
  'settings.notificationCategory.agent-turn.desc': 'The main agent finished its turn and is ready for input.',
  'settings.notificationCategory.subagent': 'Subagent finished',
  'settings.notificationCategory.subagent.desc': 'A subagent completed its turn. The noisiest category on parallel work. Requires the Claude Code hook bridge — without it, subagent turns are reported as ordinary agent turns.',
  'settings.notificationCategory.approval': 'Awaiting approval',
