  // Command Deck D1 — the deterministic "welcome home" briefing card.
  // The headline and the while-away line are assembled in the RENDERER from
  // structured counts, so every fragment below is a whole sentence/clause with a
  // {count} (or {items} / {clauses}) placeholder and its own one/other variants.
  // Main ships numbers only — it has no locale.
  // Settings — briefing toggles.
  // Command Deck — the control bar (Mode·Loop·Schedules) is component-owned.
  // Command Deck P3d — orchestrator schedules (reboot-surviving).
  // M1.5 — per-workspace orchestrator: schedules belong to a workspace.
  // Loop engineering v1 — the one-click loop.
  // Loop setup modal (the inline dock form overflowed — promoted to an overlay).
  // Orchestrator wave 2 — the pinned task-ledger panel.
  // The panel shows five rows and keeps the rest behind this toggle — it is
  // pinned above the conversation and must not grow until it owns the deck.
  // The ledger read is capped, so an expanded list is not always the whole
  // ledger — say what is on screen rather than implying completeness.
  // operator-join (design §3) — collapsed-by-default discovery section + the
  // join-confirm dialog. The collapse IS the intent gate: private channel names
  // do not exist on screen until the section is expanded.
  // Two sentences. The SECOND states the §2.1.1 contract verbatim (a durable
  // record is appended and shown to every member) — do NOT delete it.
