  'botRecipes.common.refused': "If a worker is refused, tell me why in one line. A missing sign-in, a connection not given to you, or tools not picked yet are things I fix in Plugins › Connectors.",
  'botRecipes.notionMeetingDigest.title': "Meeting notes digest",
  'botRecipes.notionMeetingDigest.hint': "Reads last week's meeting notes in Notion and lists decisions, owners and open questions.",
  'botRecipes.notionMeetingDigest.job': "Read the meeting notes in my Notion from the past seven days. Report in this chat, one section per meeting with a link to its page: what was decided, each next step with who owns it and by when, and the questions still unanswered. End with the follow-up messages you would send, written out for me to copy.",
  'botRecipes.notionStalePages.title': "Stale pages report",
  'botRecipes.notionStalePages.hint': "Finds Notion pages nobody has touched in months, and pages that repeat each other, for you to tidy.",
  'botRecipes.notionStalePages.job': "Look through my Notion for pages not edited in the last 90 days and for pages that cover the same topic. Report them in this chat as a short list per area: the page, when it last changed, and whether you would archive it, merge it into another page (say which) or keep it. I decide and make the changes.",
  'botRecipes.figmaHandoff.title': "Design handoff notes",
  'botRecipes.figmaHandoff.hint': "Turns a Figma frame you link into build notes: layout, sizes, colours, text styles and components.",
  'botRecipes.figmaHandoff.job': "When I link a Figma file or frame, read it and write build notes for a developer in this chat: layout and spacing, sizes, colours and text styles (with their style or variable names when the file has them), the components used and their variants, and the states the design shows. List what the design leaves unclear as questions for the designer.",
  'botRecipes.canvaCopyCheck.title': "Design copy check",
  'botRecipes.canvaCopyCheck.hint': "Proofreads the text of a Canva design: typos, terms used two ways, dates and prices that disagree.",
  'botRecipes.canvaCopyCheck.job': "When I name a Canva design, read its text and check it: spelling and grammar, one thing called by different names, dates, prices and numbers that disagree between pages, and a missing call to action. Report each issue in this chat with the page it is on and a suggested fix; I apply the fixes.",
  'botRecipes.linearStandup.title': "Issue standup",
  'botRecipes.linearStandup.hint': "Sums up what moved in Linear since the last workday: done, started, blocked and overdue.",
  'botRecipes.linearStandup.job': "Read my Linear issues that changed since the previous workday. Report in this chat, grouped by team or project: what was completed, what started, what is blocked and why, and what is past its due date, naming each item's assignee. Keep it to what changed.",
  'botRecipes.atlassianSprint.title': "Sprint status",
  'botRecipes.atlassianSprint.hint': "Reports the active Jira sprint's progress and blockers, and the Confluence pages that changed.",
  'botRecipes.atlassianSprint.job': "Read the active Jira sprints of my projects and report in this chat: how much of each sprint is done, issues that are blocked or have not moved for three days, and work added after the sprint started. Then list the Confluence pages edited in the past week with one line each on what changed. Link every issue and page.",
  'botRecipes.asanaDueSoon.title': "Due this week",
  'botRecipes.asanaDueSoon.hint': "Lists Asana tasks that are overdue or due in the next seven days, by project.",
  'botRecipes.asanaDueSoon.job': "Read my Asana tasks and report in this chat, grouped by project: overdue tasks first, then tasks due in the next seven days, each with its assignee and due date. Point out tasks in those projects with no assignee or no due date. Suggest changes for me to make rather than making them.",
  'botRecipes.githubWeek.title': "Repository week",
  'botRecipes.githubWeek.hint': "A weekly GitHub summary: merged pull requests, reviews waiting and new issues.",
  'botRecipes.githubWeek.job': "Ask me which GitHub repositories to cover if I have not said. Read the past seven days there and report in this chat: pull requests merged (one line each on what changed), pull requests waiting for a review and for how long, and new issues, bugs first. Link each item.",
  'botRecipes.gmailTriage.title': "Inbox triage",
  'botRecipes.gmailTriage.hint': "Sorts unread Gmail into needs a reply, read later and can skip, and drafts the replies.",
  'botRecipes.gmailTriage.job': "Read the unread mail in my Gmail inbox. Report in this chat in three groups: needs a reply (who, what they ask, by when), worth reading later, and safe to skip. For each mail that needs a reply, write a short draft I can copy. Never send, label, archive or delete mail.",
  'botRecipes.meetingPrep.title': "Meeting prep",
  'botRecipes.meetingPrep.hint': "Briefs you on each of today's meetings from your Google Calendar and related Gmail threads.",
  'botRecipes.meetingPrep.job': "Read today's events in my Google Calendar and, for each meeting with other people, the recent Gmail threads with them or on that subject. Report in this chat, one meeting at a time in order: the time, who attends, what it is about, what was said lately, and what I may want to raise or prepare.",
  'botRecipes.freeSlots.title': "Free time finder",
  'botRecipes.freeSlots.hint': "Finds open slots and clashes in your Google Calendar; you book the meeting yourself.",
  'botRecipes.freeSlots.job': "When I ask for time for a meeting, read my Google Calendar and propose three to five open slots that fit the length and working hours I give, with what is booked around each. Also point out events that overlap in the next two weeks. Write the invitation text for me to send; never create or change events.",
  'botRecipes.sheetReport.title': "Spreadsheet report",
  'botRecipes.sheetReport.hint': "Reads a Google Sheet you name and reports totals, changes and values that look wrong.",
  'botRecipes.sheetReport.job': "Ask me which Google Sheet and which tabs to follow if I have not said. Read it and report in this chat: the main totals and how they changed since the previous week, the biggest movers, and values that look wrong (blanks, outliers, totals that do not add up). Put the figures in a small table.",
  'botRecipes.driveStaleFiles.title': "Drive clean-up list",
  'botRecipes.driveStaleFiles.hint': "Finds old, duplicated and very large files in Google Drive for you to review.",
  'botRecipes.driveStaleFiles.job': "Look through my Google Drive for files not changed in a year, files that look like copies of each other, and the largest files. Report them in this chat as a list per folder with the name, last change and size, and say what you would delete, move or keep. I do the clean-up.",
  'botRecipes.slackCatchUp.title': "Slack catch-up",
  'botRecipes.slackCatchUp.hint': "Summarises the Slack channels you name since the last workday, mentions first.",
  'botRecipes.slackCatchUp.job': "Ask me which Slack channels to follow if I have not said. Read what was posted there since the previous workday and report in this chat: first the messages that mention me or ask me something, then each channel's main threads in two or three lines with a link. Draft replies I may want to post, but never post them.",
  'botRecipes.slackDecisions.title': "Decision log",
  'botRecipes.slackDecisions.hint': "Collects the week's decisions from your Slack channels into one list.",
  'botRecipes.slackDecisions.job': "Ask me which Slack channels to follow if I have not said. Read the past week there and list in this chat every decision made: what was decided, who decided or agreed, the date and a link to the message. Then list the discussions that ended without a decision.",
